import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def to_dt(value, cell=None):
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, (int, float)):
        fmt = (cell.number_format if cell is not None else "") or ""
        if any(tok in fmt for tok in ("y", "m", "d", "Y", "M", "D")):
            return datetime(1899, 12, 30) + timedelta(days=float(value))
        return None

    s = str(value).strip()
    if not s:
        return None

    for fmt in (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
        "%m/%d/%Y %H:%M:%S",
        "%m/%d/%Y",
        "%d-%m-%Y",
        "%Y/%m/%d",
    ):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass

    try:
        return datetime.fromisoformat(s)
    except Exception:
        return None

b2_cell = vws["B2"]
b2 = to_dt(b2_cell.value, b2_cell)

rows = list(range(4, 15))
base_selected = {}

for r in rows:
    c_cell = vws.cell(row=r, column=3)
    d_cell = vws.cell(row=r, column=4)
    c = to_dt(c_cell.value, c_cell)
    d = to_dt(d_cell.value, d_cell)
    base_selected[r] = (
        b2 is not None
        and c is not None
        and d is not None
        and b2 > c
        and b2 < d
    )

selected_rows = [r for r in rows if base_selected[r]]
bottom_selected_row = max(selected_rows) if selected_rows else None

for r in rows:
    if bottom_selected_row is not None and r <= bottom_selected_row:
        ws.cell(row=r, column=5).value = "Select Period"
    else:
        ws.cell(row=r, column=5).value = "Do Not Select"

print("B2:", b2)
print("Selected rows:", selected_rows)
print("Bottom selected row:", bottom_selected_row)
print("E4:E14:", [ws.cell(row=r, column=5).value for r in rows])

wb.save(OUT)
